// ===================================================================
// UC-42: Calorie Adaptive Redistribution Algorithm
// Inputs: meal log (webhook body), active meal plan, user biometrics
// ===================================================================

const webhookBody  = $('On New Meal Logged').first().json.body;
const mealPlan     = $('Fetch Active Meal Plan').first().json;
const userProfile  = $('Fetch User Biometrics (TDEE)').first().json;
const allItems     = $('Fetch Meal Plan Items').all().map(i => i.json);

// --- Guard: missing data ---
if (!mealPlan || !mealPlan._id) {
  return [{ json: { success: false, route: 'ERROR', reason: 'No active meal plan found for today.' } }];
}
if (!userProfile || !userProfile.tdee) {
  return [{ json: { success: false, route: 'ERROR', reason: 'User TDEE profile not found.' } }];
}

// --- Core values ---
const userId       = webhookBody.user_id;
const mealLogId    = webhookBody.meal_log_id || '';
const contractId   = webhookBody.contract_id || '';
const mealType     = webhookBody.meal_type;          // e.g. 'breakfast', 'lunch', 'dinner', 'snack'
const actualCal    = Number(webhookBody.actual_calories) || 0;
const loggedAt     = new Date(webhookBody.logged_at || new Date());
const loggedHour   = loggedAt.getHours();

// Find the planned target calories for this meal slot (sum across all recipe items of same meal_type)
const slotItems    = allItems.filter(item => item.meal_type === mealType);
const plannedCal   = slotItems.reduce((sum, item) => sum + (item.target_calories || 0), 0);
const deltaCal     = actualCal - plannedCal;         // positive = overeating, negative = undereating

// TDEE thresholds
const tdee             = Number(userProfile.tdee);
const criticalThreshold = tdee * 0.15;              // 15% TDEE

// --- Macro redistribution helper ---
// Keeps macros within WHO-safe ratio: Protein 15-35%, Carbs 45-65%, Fat 20-35%
function redistributeMacros(deltaCalories, numSlots) {
  if (numSlots === 0) return { deltaPerSlot: 0, proteinDelta: 0, carbsDelta: 0, fatDelta: 0 };
  const deltaPerSlot = deltaCalories / numSlots;
  // Safe macro split: 30% Protein, 45% Carbs, 25% Fat (kcal ratios)
  return {
    deltaPerSlot: Math.round(deltaPerSlot),
    proteinDelta: Math.round((deltaPerSlot * 0.30) / 4),  // 4 kcal/g protein
    carbsDelta:   Math.round((deltaPerSlot * 0.45) / 4),  // 4 kcal/g carbs
    fatDelta:     Math.round((deltaPerSlot * 0.25) / 9),  // 9 kcal/g fat
  };
}

// --- Build base output ---
let output = {
  success:       true,
  user_id:       userId,
  meal_log_id:   mealLogId,
  contract_id:   contractId,
  meal_plan_id:  String(mealPlan._id),
  meal_type:     mealType,
  actual_cal:    actualCal,
  planned_cal:   plannedCal,
  delta_cal:     deltaCal,
  tdee:          tdee,
  route:         'NORMAL',
  update_payload:   [],
  alert_payload:    null,
  next_day_payload: null,
  notification: {}
};

// ===================================================================
// PHASE 1 — CRITICAL DEVIATION CHECK (>15% TDEE)
// ===================================================================
if (Math.abs(deltaCal) >= criticalThreshold) {
  output.route = 'CRITICAL';
  output.alert_payload = {
    customer_meal_log: mealLogId,
    contract_id:       contractId,
    calculated_delta_calories: deltaCal,
    nutritionist_review: '',
    create_at: new Date().toISOString()
  };
  output.notification = {
    user_id: userId,
    title: '⚠️ Calorie Alert',
    body: `You ${deltaCal > 0 ? 'exceeded' : 'missed'} your calorie target by ${Math.abs(Math.round(deltaCal))} kcal (>${Math.round(Math.abs(deltaCal)/tdee*100)}% of TDEE). Your nutritionist has been alerted.`,
    type: 'alert'
  };
  return [{ json: output }];
}

// ===================================================================
// PHASE 2 — FIND REMAINING INCOMPLETE MEAL SLOTS TODAY
// meal_types ordered by typical schedule
// ===================================================================
const MEAL_ORDER = ['breakfast', 'snack', 'lunch', 'dinner'];
const currentMealIndex = MEAL_ORDER.indexOf(mealType);

// Remaining = items of a later meal_type (in standard order) that haven't been logged today
const completedTypes = [mealType]; // current meal is just being completed
const remainingItems = allItems.filter(item => {
  const itemIndex = MEAL_ORDER.indexOf(item.meal_type);
  return itemIndex > currentMealIndex && !completedTypes.includes(item.meal_type);
});

// Unique remaining meal types
const remainingTypes = [...new Set(remainingItems.map(i => i.meal_type))];

// ===================================================================
// PHASE 3 — LATE NIGHT EXCEPTION: no more meals today
// ===================================================================
if (remainingTypes.length === 0 || loggedHour >= 21) {
  output.route = 'LATE_NIGHT';
  // Calculate next day breakfast date
  const nextDay = new Date(loggedAt);
  nextDay.setDate(nextDay.getDate() + 1);
  nextDay.setHours(0, 0, 0, 0);
  output.next_day_payload = {
    user_id:      userId,
    target_date:  nextDay.toISOString(),
    meal_type:    'breakfast',
    delta_cal_carry: Math.round(deltaCal),
    ...redistributeMacros(deltaCal, 1)
  };
  output.notification = {
    user_id: userId,
    title: '🌙 Late Night Adjustment',
    body: `Your ${deltaCal > 0 ? 'extra' : 'missed'} ${Math.abs(Math.round(deltaCal))} kcal from tonight has been carried over to tomorrow's breakfast.`,
    type: 'system'
  };
  return [{ json: output }];
}

// ===================================================================
// PHASE 4 — NORMAL FLOW: redistribute delta across remaining slots
// One MongoDB update payload per remaining meal_type for batch efficiency
// ===================================================================
const numRemainingSlots = remainingTypes.length;
const macros = redistributeMacros(deltaCal, numRemainingSlots);

output.update_payload = remainingTypes.map(type => {
  // Sum current target_calories for this slot
  const typeItems = remainingItems.filter(i => i.meal_type === type);
  const currentTarget = typeItems.reduce((s, i) => s + (i.target_calories || 0), 0);
  // Subtract delta share (if overate, reduce future; if underate, increase future)
  const newTarget = Math.max(100, currentTarget - macros.deltaPerSlot); // floor 100 kcal safety
  return {
    meal_type:            type,
    item_ids:             typeItems.map(i => String(i._id)),
    original_target_cal:  Math.round(currentTarget),
    new_target_calories:  Math.round(newTarget),
    protein_delta_g:      macros.proteinDelta,
    carbs_delta_g:        macros.carbsDelta,
    fat_delta_g:          macros.fatDelta,
    meal_plan_id:         String(mealPlan._id)
  };
});

output.notification = {
  user_id: userId,
  title: '🔄 Meal Plan Updated',
  body: `Your remaining ${numRemainingSlots} meal${numRemainingSlots > 1 ? 's have' : ' has'} been auto-adjusted by ${Math.abs(Math.round(macros.deltaPerSlot))} kcal each to stay on track.`,
  type: 'system'
};

return [{ json: output }];

// Batch update: update all remaining meal slot target_calories in one loop
const payload = $json;
const updates = payload.update_payload || [];

const results = [];
for (const slot of updates) {
  // Build update filter and update doc for each meal_type's items
  results.push({
    filter: { meal_plan_id: slot.meal_plan_id, meal_type: slot.meal_type },
    update: {
      $set: {
        target_calories: slot.new_target_calories,
        'macro_targets.protein': { $ifNull: ['$macro_targets.protein', 0] },
        adjusted_by_uc42: true,
        adjusted_at: new Date().toISOString()
      }
    }
  });
}

// Pass result forward for MongoDB update node
return [{ json: { ...payload, db_updates: results, update_count: results.length } }];
